# -*- coding: utf-8 -*-
"""Deutschland / Klasse 7（Biologie, Chemie, Physik）"""
from de_sci import H, nq, num


def f_dichte(R):
    stoffe = [("Aluminium", 2.7), ("Eisen", 7.9), ("Kupfer", 8.9), ("Blei", 11.3), ("Glas", 2.5), ("Eis", 0.9)]
    k = R.choice(["rho", "rho", "m", "V"])
    st, rho = R.choice(stoffe)
    V = R.choice([2, 4, 5, 10, 20, 50, 100])
    m = rho * V
    if k == "rho":
        return nq("Ein Körper hat das Volumen %s cm³ und die Masse %s g. Wie groß ist seine Dichte?" % (num(V), num(m)), rho,
                  [V / m, m * V, m - V, rho * 10], "g/cm³", "ρ = m : V = %s g : %s cm³ = %s g/cm³. Das passt zu %s." % (num(m), num(V), num(rho), st))
    if k == "m":
        return nq("%s hat die Dichte %s g/cm³. Welche Masse haben %s cm³ %s?" % (st, num(rho), num(V), st), m,
                  [V / rho, rho + V, m * 10], "g", "m = ρ · V = %s g/cm³ · %s cm³ = %s g." % (num(rho), num(V), num(m)))
    return nq("Ein Stück %s (ρ = %s g/cm³) hat die Masse %s g. Wie groß ist sein Volumen?" % (st, num(rho), num(m)), V,
              [m * rho, m - rho, V * 10], "cm³", "V = m : ρ = %s g : %s g/cm³ = %s cm³." % (num(m), num(rho), num(V)))


def f_v(R):
    k = R.choice(["v", "v", "s", "t", "kmh"])
    if k == "v":
        s, t = R.choice([(100, 20), (200, 25), (60, 12), (400, 50), (1500, 300), (90, 15), (120, 8), (300, 60)])
        return nq("Ein Radfahrer legt %s m in %d s zurück. Wie groß ist seine Durchschnittsgeschwindigkeit?" % (num(s), t), s / t,
                  [t / s, s * t, s - t], "m/s", "v = s : t = %s m : %d s = %s m/s." % (num(s), t, num(s / t)))
    if k == "s":
        v, t = R.choice([(5, 30), (12, 20), (3, 120), (25, 40), (8, 15), (15, 60)])
        return nq("Ein Fahrzeug fährt %d m/s schnell. Welche Strecke legt es in %d s zurück?" % (v, t), v * t,
                  [v / t, t / v, v + t], "m", "s = v · t = %d m/s · %d s = %s m." % (v, t, num(v * t)))
    if k == "t":
        s, v = R.choice([(100, 5), (300, 10), (2400, 40), (900, 15), (60, 4), (1000, 20)])
        return nq("Wie lange braucht ein Läufer für %s m, wenn er %d m/s schnell ist?" % (num(s), v), s / v,
                  [s * v, v / s, s - v], "s", "t = s : v = %s m : %d m/s = %s s." % (num(s), v, num(s / v)))
    v = R.choice([5, 10, 15, 20, 25, 30])
    return nq("Ein Auto fährt %d m/s. Wie viele km/h sind das?" % v, v * 3.6, [v / 3.6, v * 60, v * 36], "km/h",
              "Umrechnung: m/s · 3,6 = km/h, also %d · 3,6 = %s km/h." % (v, num(v * 3.6)))


def f_kraft(R):
    k = R.choice(["F", "F", "m", "feder"])
    if k == "F":
        m = R.choice([0.2, 0.5, 1, 2, 5, 12, 40, 75])
        return nq("Welche Gewichtskraft wirkt auf einen Körper mit der Masse %s kg? (g ≈ 10 N/kg)" % num(m), m * 10, [m, m / 10, m * 100], "N",
                  "F = m · g = %s kg · 10 N/kg = %s N." % (num(m), num(m * 10)))
    if k == "m":
        F = R.choice([5, 20, 50, 150, 600, 800])
        return nq("Ein Kraftmesser zeigt %d N an. Welche Masse hängt daran? (g ≈ 10 N/kg)" % F, F / 10, [F, F * 10, F / 100], "kg",
                  "m = F : g = %d N : 10 N/kg = %s kg." % (F, num(F / 10)))
    D, F = R.choice([(20, 4), (50, 10), (10, 3), (40, 6), (25, 5)])
    return nq("Eine Feder dehnt sich bei 1 N um %s cm. Um wie viel dehnt sie sich bei %d N? (Hookesches Gesetz)" % (num(D / 10), F), D / 10 * F,
              [D / 10 + F, F / (D / 10), D * F], "cm", "Die Dehnung ist proportional zur Kraft: %s cm · %d = %s cm." % (num(D / 10), F, num(D / 10 * F)))


def f_linse(R):
    k = R.choice(["D", "D", "f"])
    if k == "D":
        f = R.choice([0.1, 0.2, 0.25, 0.5, 0.4, 2, 0.05, 0.125, 1, 0.8, 0.02, 0.04])
        return nq("Eine Sammellinse hat die Brennweite %s m. Wie groß ist ihre Brechkraft?" % num(f), 1 / f, [f, 1 / f / 10, 10 * f], "dpt",
                  "D = 1 : f = 1 : %s m = %s dpt." % (num(f), num(1 / f)))
    D = R.choice([2, 4, 5, 10, 20, 8, 25, 40, 50, 1])
    return nq("Eine Sammellinse hat die Brechkraft %d dpt. Wie groß ist ihre Brennweite?" % D, 1 / D * 100, [D, D * 10, 100 / D / 10], "cm",
              "f = 1 : D = 1 : %d dpt = %s m = %s cm." % (D, num(1 / D), num(100 / D)))


